    interpretation: "端平入洛是南宋战略冒进的典型。理宗亲政未久，史弥远专权二十年的积弊未除，便欲以恢复之功树立威望；郑清之、赵范、赵葵等以恢复为名，迎合上意。反对者并非不思恢复，而是洞见南宋财政枯竭、军储不足、千里馈粮不可持久的现实。入洛之师，以两淮之粮养中原之兵，进不能守，退不能全，本无胜算。此败不仅尽丧宋军精锐与物资，更授蒙古南侵以口实，使宋蒙由盟友变为死敌。此后四十余年，南宋在蒙古三路压迫下苦撑，国力耗尽，终亡于崖山。其教训在于以政治需要凌驾军事规律，以侥幸之心行险之战。",
