    era: "嘉定元年",
    year: {
      start: 1208
    },
    summary: "嘉定元年（1208）六月，宋金重订和约，结束了开禧二年（1206）韩侂胄北伐以来的战争状态。宋宁宗赵扩在杨皇后与礼部侍郎史弥远主持下，函韩侂胄、苏师旦首级献金，金军退出新占州军。和约定宋金为伯侄之国，宋帝称金帝为伯父；岁币由银绢各二十万增至各三十万，另一次性纳犒军银三百万两。这是南宋对金最后一纸正式和约，宋金两朝皆因连年征战而疲敝，漠北蒙古已告崛起，双方由对峙均衡同趋衰落。",
    background: "开禧二年（1206）五月，平章军国事韩侂胄为固权立功，兴开禧北伐，兵分三路攻金。宋军初取泗州、虹县，旋即宿州、唐州之败，全线溃退。金廷以仆散揆为帅大举反攻，陷真州、围六合，江淮震动；四川宣抚副使吴曦又据兴州叛宋降金，受金封为蜀王，宋西部门户洞开。开禧三年（1207）二月，安丙、杨巨源等诛吴曦，蜀地复定，但宋已无力再战。韩侂胄罢免苏师旦，起用丘崈为江淮宣抚使，遣方信孺赴金营议和。金帅完颜匡开列五事：割两淮、增岁币、纳犒军银、斩韩侂胄函首来献、改叔侄为伯侄之国。方信孺回报，韩侂胄大怒，欲再战。此时金章宗完颜璟亦病重，北边铁木真已于1206年统一漠北，金朝两面受压，同样急于息兵。开禧三年十一月三日，史弥远与杨皇后密谋，令中军统制夏震杀韩侂胄于玉津园，苏师旦亦诛。宋廷改命王柟使金，和议遂成。",
