          "与绍兴和议（1141）相比，嘉定和议在名义上略优：宋帝不再称臣而称侄，岁币之外却又新增犒军银三百万两，几竭东南一岁之入。金人原索「犒军银三百万两」，宋廷倾内藏、括州郡方才凑足。韩侂胄首至金，金章宗命悬于通衢示众，备极屈辱。宋廷以「和戎」告天地宗庙，朝野侧目，太学生有「自古人主有以匹夫之耻为耻者，未闻以匹夫之辱为辱」之讥。",
          "和议既定，史弥远以诛韩之功拜右丞相，杨皇后一族并进，主和派尽据要津。宋宁宗下诏改元嘉定，大赦天下，以息兵为治。此后十七年，史弥远独相专政，南宋朝政转入权臣时代。岁币、犒军银与战争善后之费，则悉数摊入东南赋税，民生日困。"
