    interpretation: "嘉定和议的深层逻辑，在于宋金双方都已无力支撑战争，而朝局内部的政治清算先于战场胜负落定。韩侂胄以北伐固权，败后反被主和派借金人之手诛灭；史弥远、杨皇后以函首谢敌换取和局，既免于亡国之祸，也为自身十七年专权铺路。对金而言，泰和南征虽胜，所得止于岁币与仇敌首级，而漠北蒙古已在此期间完成统一。金章宗完颜璟以「伯父」之名得虚尊，却把金朝钉在了两线作战的死局之上：嘉定四年（1211）野狐岭之败、贞祐二年（1214）迁都汴京，皆种因于此。故嘉定和议表面上是金朝最大的一次胜利，实为宋金两朝同归于尽的起点。宋以财赋换苟安，金以虚名换实祸，蒙古于两疲之间坐收渔利，宋金对峙三百年的格局由此进入尾声。",
