    summary: "开禧二年（1206）五月，宋宁宗在权臣韩侂胄主持下下诏伐金，兵分三路进取中原，史称开禧北伐。宋军出师即败：东路溃于宿州、唐州，西路统帅吴曦据兴州叛宋降金，金军乘势分道反攻，渡淮南下，直抵长江北岸，围困楚州、襄阳。战事绵延一年有余，宋廷力屈求和。开禧三年（1207）十一月，礼部侍郎史弥远与杨皇后密令中军统制夏震诛韩侂胄，函其首以献金人。嘉定元年（1208）三月和议成，宋金改伯侄之国，岁币增至银、绢各三十万两匹，另输犒军钱三百万贯。南宋国势由此再损，国柄则自韩侂胄转入史弥远之手。",
    background: "南宋自绍兴和议（1141）以来偏安江南已逾六十年；隆兴和议（1164）后，宋金为叔侄之国，岁币银、绢各二十万两匹，边境晏然者四十载。然朝野上下，恢复之念未尝绝。淳熙以后，金国渐见疲态：章宗在位，北边蒙古诸部日逼，内有饥荒与吏治之敝，国势已非昔比。南宋朝堂之上，主战之声渐起。韩侂胄以吴皇后外戚起家，庆元元年（1195）倾覆宗室赵汝愚，独揽朝政，拜太师，封平原郡王。他兴庆元党禁，罢斥朱熹等道学之臣，以钳制清议。权位虽隆，恩遇不深，韩侂胄遂思以「恢复中原」立不世之功，借战端以固权位、镇异己。开禧元年（1205）起，宋廷于沿边增兵积粮，联络中原忠义。叶适力谏不可轻启战端，不报。一场以巩固权位为出发点的北伐，就此酿成。",
