          "权位既固，韩侂胄仍忧名不正、恩不深，遂以「恢复中原」自任，欲立奇功以震朝野。开禧二年（1206）四月，追封岳飞为鄂王；五月，夺秦桧王爵，改谥「缪丑」。一朝之间，主战声浪大作。辛弃疾被起用知绍兴府兼浙东安抚使，陆游闲居山阴亦赋诗壮之。唯叶适上疏力谏，谓四十余年不知兵，未可言战；韩侂胄不纳，反出叶适于外。",
