    interpretation: "开禧北伐之败，非止军事之败，实为南宋积疾之总暴发。韩侂胄以恢复为名，所图实为权位；战与和皆从一人之私计，而非从国力之实计。庆元党禁，清议之士尽去，朝廷无谏诤之音，边报多为虚功，决策一误再误。出师之后，东路溃于宿州，西路叛于兴州，独毕再遇一军撑持江淮，军备弛坏、武人离心，暴露无遗。嘉定和议虽成，岁币增输，国力坐困；金国亦师老兵疲，两败俱伤。而其时蒙古铁骑已于漠北崛起，南北强弱之局正在悄然易位。数十年后，蒙宋联军灭金，南宋终亦覆于崖山。权臣以国运搏一己之功，其代价之巨，开禧一朝已见端倪。",
