          "金世宗乘南宋议和未定、边备空虚，命仆散忠义、纥石烈志宁统大军南下。隆兴二年秋，金军渡过淮河，相继攻陷楚州、濠州、滁州，前锋直逼长江北岸，江淮大震。南宋守军节节败退，朝野惶惧。孝宗虽不甘屈服，但在军事重压之下，不得不再遣使臣赴金营请和。",
          "十月，宋遣通问使王抃赴金，与金帅仆散忠义往复磋商；继命魏杞奉国书北上。金人初欲仍循绍兴旧礼，要宋称臣；宋使以对等之礼相争，金世宗亦以内部初定、不宜久战，终于作出让步。十二月，和议条款议定，宋金战争状态终止。"
