    interpretation: "隆兴和议的深层逻辑，在于宋金双方都失去了彻底压倒对方的可能。从宋方看，符离之溃证明仓促北伐不可恃，财用与军备皆不足以支撑持久战；从金方看，世宗新立、内部初定，同样不愿久戍江淮。条款中去臣礼、减岁币，并非金人恩赐，而是南宋以战场僵局换来的外交成果，也说明南宋的地位较绍兴年间已有所上升。和议使宋金关系由单方面臣服走向名义上较为平等的叔侄之礼，南北对峙由此定型。对南宋而言，它保住了半壁江山与四十年安宁，代价则是恢复中原的政治理想被长期搁置；孝宗锐气尽消，南宋由此进入偏安求存、内政为重的乾道、淳熙时期。",
