      {
        heading: "钓鱼城下，蒙哥殒命",
        paragraphs: [
          "蒙哥汗即位后，决意完成灭宋大业。宝祐六年（1258）二月，蒙古再次兵分三路：蒙哥自率主力入四川，忽必烈率军攻鄂州，大将兀良合台自云南北上，约期会师荆湖，再顺江东下直取临安。这是宋蒙开战以来规模最大的一次攻势。蒙哥入蜀后，成都、利州、隆庆、顺庆等州或破或降，蒙古军进围合州。独有钓鱼城扼嘉陵江、渠江、涪江交汇之处，巍然不动。",
          "开庆元年（1259）二月起，蒙哥督数万大军围攻钓鱼城。守将王坚、副将张珏率军民凭险坚守，以滚木、巨石、火器击退蒙古军一次又一次进攻。蒙古军屯兵坚城之下，正值盛夏暑湿，疾疫流行，死者甚众。自二月至七月，攻围数月不能下。七月，蒙哥死于钓鱼山下，关于其死因，史书或云染疾，或云中飞石，至今未有定论。蒙哥一死，蒙古全军解围北还。",
          "蒙哥之死使蒙古的灭宋全局骤然瓦解。正在围攻鄂州的忽必烈闻讯，为争夺汗位仓促撤兵北返，兀良合台亦自南方撤军。蒙古宗王各军纷纷回师漠北，忽必烈与阿里不哥随即爆发长达四年的汗位之争。南宋抓住喘息之机暂得保全，然贾似道以鄂州之功擅权，朝政愈发败坏。战争虽暂时转入低潮，南宋的腐朽也已病入膏肓。"
        ]
      },
      {
        heading: "襄樊之围，南宋覆亡",
        paragraphs: [
          "忽必烈取得汗位后，调整灭宋方略。宋降将刘整进言先取襄阳、撤其扞蔽，忽必烈深以为然。咸淳三年（1267），蒙古开始围攻襄阳、樊城，命阿术、刘整主持其事。守将吕文焕与其兄吕文德依托坚城坚守，吕文德于围城期间病逝。蒙古军沿汉水修筑长围，训练水军，一步步切断宋军增援与粮道。宋军多次以水师突破封锁送入粮饷，皆难以持久。至元八年（1271），忽必烈建国号大元，志在必得。",
          "咸淳九年（1273）正月，元军以回回巨炮轰破樊城，守将范天顺自缢殉国，牛富力战身亡；二月，孤立无援的吕文焕以襄阳降元。六年坚守的襄樊陷落，南宋长江中游防线彻底崩溃。忽必烈随即命丞相伯颜率水陆大军沿汉水入长江，顺流东下，沿途宋军或战或降，已难组织有效抵抗。德祐二年（1276）正月，元军进至临安城外，宋恭帝奉表出降，立国三百二十年的赵宋朝廷实质覆亡。",
          "残余宋臣拥立益王赵昰、广王赵昺南走，文天祥、陆秀夫、张世杰等在福建、广东继续抗元。祥兴二年（1279）二月，元将张弘范追至崖山，宋军决战失败，陆秀夫负幼帝赵昺投海，南宋彻底灭亡。自1235年蒙古三路南侵起，至此四十四年，南北对抗最终以元朝统一天下告终。"
        ]
      }
