          "苗傅等大惧，欲闭城自守，又惧勤王军势大，乃请孟太后下诏，迎高宗还宫复位，以缓其锋。建炎三年四月初一日（戊申朔），高宗御正殿复位，复以建炎纪年，孟太后撤帘归政。高宗下诏讨伐，以韩世忠为勤王先锋，拜武胜军节度使、加检校少保，张俊、刘光世分统诸军继进。",
          "苗傅遣其弟苗翊与部将马柔吉率精兵拒于杭州东北之临平。韩世忠率先锋至，身先士卒，麾军力战，大破之，苗翊、马柔吉弃军溃走。苗傅、刘正彦知大势已去，率残部弃杭州南奔，经浙东一路入福建，沿路劫掠，众散过半。"
