          "然兵变余波，久不能平。高宗独子魏国公赵旉，在兵变中随父颠沛，复位后随驾北行，一夕宫人置金炉于地，倾覆作响，赵旉惊搐成疾，建炎三年七月夭折，年止三岁，谥曰「元懿」。高宗此后再无子嗣，皇储空虚，遂于绍兴年间选太祖七世孙赵昚入宫养育，后即位为宋孝宗，帝统复归太祖一系。",
          "是年七月，升杭州为临安府，南宋定都于斯。苗刘兵变虽旋起旋灭，却给南宋朝廷留下深创：天子为乱军所废，行在几倾，乃靖康之变以后宋室最大的一次内部危机。经此一变，行在宦官之祸暂得整肃，而高宗对武人的猜忌深入骨髓，「防内甚于防外」遂为建炎、绍兴两朝政局之底色。"
