    interpretation: "苗刘兵变以「诛宦官、清君侧」为名，实质是南渡政权内部矛盾的总爆发：其一，扈从将士与流亡朝廷在地域、利益上尖锐冲突，北籍军人久困行在，积怨一触即发；其二，北宋以来崇文抑武、压制武将的国策，与南宋初年武将地位上升的现实相抵触，扈从禁军一旦身处权力核心而又遭宦官侵克，便以废立的极端方式反弹；其三，高宗仓皇播迁、赏罚失当，天子威信坠地，乱兵方敢迫帝禅位。乱事虽二十余日即平，却暴露了南宋政权根基未固的脆弱结构。更深远的后果在心理与制度：高宗亲历武将废立之祸，对韩世忠、张俊、岳飞等拥兵之将由倚重而猜忌，绍兴年间二次收兵权、杀岳飞，皆可谓此变之直接延伸。",
