    interpretation: "庆元党禁名为禁伪学，实为韩侂胄与赵汝愚权位之争的余波。定策之功一朝翻覆，可见南宋皇权结构之下，外戚近幸与宗室宰相之争，实为权力无序的产物。其手法与北宋蔡京立元祐党人碑如出一辙：以籍记党人、禁锢仕途钳制士论，将政见之争化为诛心之狱。然权力可禁人讲学，不能禁人心向学。六年禁锢期间，朱熹讲学不辍，门人会葬近千人，民间从游益众，党禁反为理学博得道义声望，加速其传播。韩侂胄身死之后，理学不仅解禁，更上升为官学，支配元明清科举与思想七百年。以权势裁决学术者，终为学术所笑，此其明验。",
