          "依此条款，宋割唐（今河南唐河）、邓（今河南邓州）二州及陕西余地予金，商州、秦州各占其半；又裁撤沿淮戍军，金使过境时宋廷须以臣子之礼迎送。岁贡之数，较澶渊之盟时宋辽平等之交，银绢各增五万，而两国地位更由兄弟之邦降为君臣。高宗又以岳飞之死为信，示金以决意和好、再无北伐之志。",
          "绍兴十二年（1142年）三月，宋高宗遣使进誓表于金，称「世世子孙，谨守臣节」。四月，金使张通古持册书至临安，高宗行臣子之礼受册，宋金和议正式生效。八月，被拘于金国十六年的韦太后携徽宗棺椁南归。高宗以称臣纳贡之辱，换得东南半壁的安宁与皇位的稳固，而代价是中原故土与岳飞父子的性命。"
