    interpretation: "绍兴和议是南宋在军事上并不处于劣势时签订的不平等和约，其深层逻辑在于高宗的政治考量：他继承北宋强干弱枝、以文制武的家法，视武将拥兵为心腹之患，忌惮岳飞等大将实甚于忌惮金军；又欲以称臣纳贡换取金朝对其皇位的承认与韦太后南归，稳固统治正当性。后世或谓高宗惧怕钦宗南归争位，故不复北伐，此说南宋以来流传甚广，然主流学界多认为收揽兵权、求和自保方为其根本动机。和议以淮水、大散关为界，正式确立宋金南北对峙格局，南宋偏安江南百余年，岁贡成为长期财政负担；但近二十年的休兵，也使江南经济文化得以在相对安定中发展。至隆兴元年（1164年），宋金再订和约，关系由君臣改为叔侄，岁币减为银绢各二十万，国势消长与外交地位之变，于此可见。",
