          "全线撤退之际，太宗令潘美、杨业护送云、应、寰、朔四州百姓内迁。辽将耶律斜轸已乘胜攻克寰州，宋军面临的形势急转直下。监军王侁、刘文裕等人轻敌好功，力主主动出击，与辽军正面交锋。杨业深知敌势正盛，主张避其锋芒，先护百姓南撤，再伺机而动。王侁出言相激，讥讽杨业素号「杨无敌」，如今畏缩不前，莫非有异志。杨业无奈，只得率军出战，并与潘美约定在陈家谷口（今山西宁武境）埋伏强弩兵接应。",
          "杨业率军北上，耶律斜轸佯败诱敌，宋军追击中伏。杨业力战自午至暮，且战且退至陈家谷口，却见谷口空无一人——潘美、王侁已违约率军撤离。杨业拊膺大恸，率帐下残兵回身再战，身被数十创，士卒死伤殆尽，其子杨延玉亦战死于阵中。杨业马重伤不能行，为契丹所擒。他被押解至辽营后，宁死不降，不食三日而亡，年约六十。事后王侁、刘文裕被除名流放，潘美削职三级，但一代名将已殒身塞外。"
