          "端拱、淳化年间，宋廷采纳何承矩等人的建议，在河北平原西起保州（今河北保定）、东至泥姑海口（今天津塘沽一带），利用河川湖泊筑堤潴水，形成东西约九百里、纵深数十里的「塘泊」防线，以水障限制辽军骑兵驰突。对辽政策由武力进取转为消极防御。这一战略格局一直延续到景德元年（1004）澶渊之盟订立，终北宋之世，再未有大举北伐之举。"
