    interpretation: "雍熙北伐是北宋对辽由攻转守的转折点。表面上看，败因在于将帅失和、粮草不继、指挥失当；深层看，根源在宋太宗的战略误判。他先误判辽廷「主少国疑」，实则承天太后萧氏与耶律休哥、耶律斜轸等名将近臣同心协力，上下安定；再误判宋军战力，高梁河之败不过七年，未整军经武便轻率出师。太宗又以「将从中御」的方式遥控前线，东路军进退失据，正是这一指挥体制的积弊。此战之后，宋廷放弃收复燕云的打算，转而构筑塘泊防线，对辽由武力进取变为消极防御。杨业之死则成为宋代忠勇将帅悲剧的原型，深刻影响了北宋对武将既倚重又猜忌的复杂心态。",
