    interpretation: "岳飞北伐之败，非战之罪，实败于南宋政治结构。高宗赵构恐金成疾，更惧北伐若成、钦宗南归，帝位难安；武将兵权过重，又触宋初以来以文制武之家法。秦桧主和，不过秉承帝意。十二道金牌，非一道军令，乃皇权对武将之最终裁决。军事上，岳家军以步制骑、以寡击众，郾城、颍昌两役证明金军并非不可战胜；然岳飞孤军深入，两翼友军后撤，粮饷全仰朝廷，胜负实系于庙堂而非沙场。北伐虽功败垂成，却铸就「精忠报国」之精神丰碑，深刻塑造了后世的忠奸之辨与民族气节，其影响远逾一役之得失。",
