    dynasty: "宋",
    era: "熙宁三年",
    year: {
      start: 1070
    },
    summary: "保甲制是北宋熙宁三年（1070年）王安石变法时推行的乡村治安与民兵制度。其法以十家为一保、五保为一大保、十大保为一都保，家有两丁以上者抽一丁为保丁，农闲集中教阅，夜间轮差巡警，同保连坐。初衷是以民兵渐代募兵、节省冗费，恢复兵农合一的古制。该制先在开封府畿县试行，次第推广至京东、京西、河北、河东、陕西五路并及全国，熙宁九年（1076年）编成保丁六百九十余万。然终北宋一世，保甲未能取代募兵，反与募兵并行，军费有增无减；其基层治安与连坐之法则为后世王朝所沿袭，影响深远。",
    background: "北宋开国，为防范唐末五代藩镇割据重演，朝廷将兵权收归中央，以禁兵、厢兵立国，却因此背上了沉重的财政包袱。养兵之费常占国家岁入之大半，至英宗、神宗之际，国库已入不敷出。另一方面，乡村治安日渐涣散，盗贼公行，豪强与胥吏把持乡里，官府难以约束。熙宁二年（1069年），宋神宗赵顼起用王安石为参知政事，设制置三司条例司，大行新法。王安石认为，欲省军费、清盗源，必须恢复三代兵农合一之古制，使百姓农隙受训、有事为兵。熙宁三年（1070年）十二月，司农寺制定《畿县保甲条例》，先于开封府诸县试行，保甲法由此而生。",
    chapters: [
      {
        heading: "畿县立制，十家为保",
        paragraphs: [
          "熙宁三年（1070年）十二月，宋神宗赵顼采纳王安石之议，由司农寺颁行《畿县保甲条例》，先在开封府畿县试行。条例规定：乡村民户每十家组成一保，于主户中选精明有材干者一人为保长；五保即五十家组成一大保，置大保长一人；十大保即五百家组成一都保，置都保正、都副保正各一人，均以家产丰厚、材行出众者充任。各级保长不由官府任命，而由本地主户轮流充当，负责编排保内户口、督催赋役、缉捕盗贼、觉察奸宄。",
          "编入保甲的民户，凡家有两丁以上者，必须抽出一丁充当保丁。保丁于农闲时集中教习弓弩武艺，夜间以大保为单位轮差巡警，遇有盗贼即合力追捕，逃亡即行告捕。同保之内若发生强盗、杀人、放火、强奸、略人、传习妖教、造畜蛊毒等重案，保内知而不告者连坐治理。如此则军事训练、治安巡查、连保连坐三者合为一体，乡村尽归官府掌握，豪强胥吏窝藏奸宄的旧习为之一变。"
        ]
      },
      {
        heading: "推行诸路，六百万丁",
        paragraphs: [
          "畿县试行一年，开封府一带盗贼显著减少，宋神宗与王安石颇为满意，遂于熙宁四年（1071年）将保甲法推广至京东、京西、河北、河东、陕西五路，此后渐次推行于全国。熙宁六年（1073年），朝廷又令各路保丁定期赴州县教阅，技艺优长者可免除部分赋役，甚至量材授官。至熙宁九年（1076年），府界及诸路保甲已编成六百九十三万八千七百七十五人，规模之大，为前代所罕见。",
          "推行之中，流弊亦随之而生。地方官吏为邀功，往往强迫单丁、老弱、客户入保，甚至借编甲之名勒索钱财，民间骚然。熙宁七年（1074年），开封府界提点司奏报，有保丁因不堪教阅之苦而自断手指、毁伤肢体以图免役，逃亡者亦复不少。王安石虽屡下诏书约束，命提举司体量纠正，然积弊终难尽除。就治安而言，保甲确有实效，畿县盗贼衰息，京东一路岁获盗贼以千计；然其军事价值，始终未如预期般显现。"
        ]
      },
      {
        heading: "兵农之困，两制并行",
        paragraphs: [
          "王安石推行保甲的深层用意，在于以民兵渐代募兵。北宋禁兵、厢兵冗滥，岁费浩大，王安石欲以保甲练出一支可战之民，逐步裁减募兵，恢复兵农合一的古制，从根本上解决军费之困。熙宁间，朝廷曾以开封府界保丁番上填补禁军阙额，又议以保甲代义勇，然保丁未经系统训练，器械粗陋、纪律散漫，朝廷终不敢以之当战阵之任，裁兵之议遂寝。",
          "其结果，保甲与募兵两套系统并行运转，军费不仅未能节省，反因教阅、赏赐、器械、廪给之费而有所增加。元丰年间（1078—1085年），保甲法虽继续推行，其职能却逐渐转向催科赋税、逐捕盗贼、供应役使等基层事务，军事色彩日渐淡薄。司马光上《乞罢保甲札子》，痛陈其弊，斥其「更迭屯聚教习戎器，以妨农事」。王安石罢相之后，保甲虽存，强兵之初衷已基本落空。"
        ]
      },
      {
        heading: "元祐罢废，流泽后世",
        paragraphs: [
          "元丰八年（1085年），宋神宗赵顼驾崩，高太后临朝，起用司马光为相，尽废新法。元祐元年（1086年）八月，朝廷下诏罢诸路保甲教阅，保甲法基本中止。绍圣元年（1094年），宋哲宗赵煦亲政，复行新法，保甲制随之恢复，然仅存治安之责，取代募兵之议无人再提。靖康元年（1126年）金兵围汴梁，仓促征调的保丁并不能战，部分反而溃散为盗，保甲之军事功能至此彻底破产。",
          "南宋以降，保甲之制屡有兴废，而其基层治安功能为历代王朝所继承。明代里甲、清代保甲，皆可视为这一制度的流变余绪。王安石以保甲省军费、强治安的初衷，因脱离社会实际、执行流弊太多而未能实现；但保甲制将国家权力延伸至乡村、以连坐之法治理基层的做法，却深刻塑造了此后近千年的乡村治理格局，成为中国古代基层控制体系的重要一环。"
        ]
      }
    ],
    interpretation: "保甲制的兴衰，折射出北宋中央集权与财政危机之间的深刻矛盾。宋初以防弊为第一要务，兵权收归中央，养兵之费却成为财政无法承受的重负。王安石以保甲为突破口，试图在不增加赋税的前提下，将乡村劳动力转化为军事力量，实现兵农合一。这一设计在账面上堪称精妙，但在执行中，保丁既要承担农业生产，又要应付教阅、巡警之役，负担反而加重；地方官吏的强制摊派更使制度尽失民心。其根本困境在于，北宋的国防压力并未因保甲而减轻，募兵不可骤裁，于是两套系统并行，军费有增无减。保甲制最终未能实现强兵之志，却开创了国家权力直接控制乡村的治理模式，成为后世里甲、保甲制度的源头。",
