          "书中所记可与张择端《清明上河图》相互印证，一图一文，共同定格了北宋东京的城市面貌。它还开创了「梦华体」笔记传统：南宋的《都城纪胜》《西湖老人繁胜录》《武林旧事》《梦粱录》等书，皆仿其体例记录南宋临安的城市生活，形成了一个书写城市记忆的著作序列。从此，城市烟火与王朝兴衰一样，成为历史书写的重要主题。"
