          "新政推行年余，明黜陟使庸碌官员不安，抑侥幸断了权贵子弟的恩荫之路，朝中怨谤渐集。夏竦制造流言，攻讦范仲淹、富弼结为朋党，仁宗心生疑忌。庆历五年（1045）初，范仲淹罢参知政事，出知邠州，富弼、欧阳修、韩琦相继罢政外放，各项新法或废或停，新政遂止。然其改革主张，至二十余年后王安石熙宁变法，多被重拾。"
