    interpretation: "范仲淹的一生，是从寒门书生到士林领袖的完整轨迹。他经略西北之所以见效，关键在于将筑城、屯田、练兵、抚羌四者结合，以持久防御化解西夏骑兵的机动优势，这一方略后被李纲、虞允文等南宋将臣继承。庆历新政虽仅年余即罢，却是宋代第一次系统革除冗官、冗兵、冗费的尝试，为王安石熙宁变法提供了先声与镜鉴。更重要的是，他以「先忧后乐」的精神，为宋代士大夫树立了以天下为己任的政治品格，士风为之一变。《宋史》论其「一时士大夫矫厉尚风节，自仲淹倡之」，正道出他超越事功、化及士林的历史地位。",
