    interpretation: "陆游的一生，是南宋主战派命运的缩影。其悲剧并非才具不足，而在于南宋立国的根本格局：以和议求苟安，以文制武、防范武将的家法未改，主战士人便永远只能在起落之间空耗岁月。孝宗隆兴北伐、宁宗开禧北伐，两次恢复尝试都败于内政先于军事，陆游的九千余首诗，正是一部南渡士人屈辱与不甘的心灵史。他将恢复之志熔铸入诗，使宋诗在苏轼之后别开生面，雄浑悲壮一派由他而立。绝笔《示儿》以家祭之嘱寄托国仇，将私人亲情升华为家国情怀，千百年来已成为中华民族集体记忆的一部分。",
