    interpretation: "沈括之成就，根植于北宋「格物穷理」的士大夫传统。北宋右文，士大夫以博学为尚；王安石变法以来，讲求实用、考求制度之风更盛，沈括正是这一时代之产儿。他以目验、实验与推理考辨自然万物，已具近世科学之精神；然其学终究寄于笔记，未能成为体系化之专门学问，亦无传人继之，故其身后中国科学未能由此进为独立之业。此书之成，源于沈括政治失意后退居著述——沈括之不幸，反成中国文化之大幸。其所载活字印刷、磁偏角、石油诸条，为后世技术演进留下最早之文献坐标，至今仍为考索中国古代科技之第一典籍。",
