    summary: "米芾（1051—1107），初名黻，字元章，号鹿门居士、襄阳漫士、海岳外史。祖籍太原，先世徙居襄阳，晚年定居润州（今江苏镇江），官终礼部员外郎、知淮阳军，世称米南宫。北宋著名书画家、鉴赏家。书法博采晋唐、尤得王献之笔意，与苏轼、黄庭坚、蔡襄并称「宋四家」；山水画创「米点皴」，开米家山水一派；又嗜奇石、拜石称兄，世称「米颠」。其书画理论与作品沾溉后世极深。",
