          "米芾的画学思想集中见于《画史》一书。他提出「平淡天真」的审美理想，推重董源、巨然的江南山水，贬斥画工的板滞与俗格，主张以文人意趣入画。这一理论经由后世特别是明代董其昌等人的阐扬，成为文人画正宗观念的重要来源。可以说，米芾在笔墨技法与理论倡导两端，都为后世文人山水画开辟了道路。"
