          "嘉祐二年（1057），欧阳修权知贡举，与韩绛、范镇、梅挚、王珪同主考。当时士子好作奇涩浮夸之文，他痛加排抑，凡内容空疏者一概落第，而将苏轼、苏辙、曾巩拔置前列。苏轼在《谢欧阳内翰书》中愿「长为门下之士」。他又赏识布衣苏洵，读其文即荐于朝；赠王安石诗云「翰林风月三千首，吏部文章二百年」，极意推挽。自此苏氏父子、曾巩、王安石皆出其门或得其力，宋代古文彬彬称盛，宋文六家格局由此奠定，与唐之韩愈、柳宗元并称唐宋八大家。"
