    interpretation: "欧阳修的历史贡献，不止于个人文章成就，而在于他以文坛与政坛的双重身份，完成了宋代士风的重建。五代以来士子习于浮华，文人依附权贵；欧阳修以韩愈为宗，把「道」重新置于「文」之上，使文章成为表达政见、承载伦理的工具，这正切合宋王朝崇儒重教、以文驭武的立国方向。他知贡举时不取浮华而取实学，所拔苏轼、曾巩、王安石后来各擅胜场，宋文由此自成一家，与唐诗并峙。史学上，《新五代史》《新唐书》两书将尊王道、正名分的评判注入史书叙事，影响后世修史近千年。他是北宋文化由因袭走向自新的关键人物。",
