          "建炎四年（1130），秦桧携家眷自金南归，自言杀监守、夺舟浮海而至。群臣多疑其为金人内应，宰相范宗尹力荐之。绍兴元年（1131）二月，秦桧拜参知政事；八月，擢右仆射、同中书门下平章事，首次拜相。次年因与宰相吕颐浩政争失利，罢相奉祠闲居。绍兴八年（1138）三月，复拜右仆射，自此独居相位近二十年，再未离开南宋权力中枢。"
