          "绍兴十一年，宋军在柘皋、颍昌一线屡败金军，高宗与秦桧却急于收兵权。四月，韩世忠、张俊并为枢密使，岳飞为枢密副使，三大将皆罢兵柄。十一月，金使萧毅至临安，宋金和议成：宋向金称臣，岁贡银二十五万两、绢二十五万匹，以淮水为界，割唐、邓二州予金。高宗于国书中自称「臣构」，南宋由此偏安江南一百余年，中原恢复之志尽付东流。"
