          "十二月二十九日（公历1142年1月27日），岳飞被赐死于大理寺狱，年三十九岁；岳云、张宪弃市。狱成之际，韩世忠不平，诣秦桧诘问其实，桧以「莫须有」三字对之，世忠怫然曰：「『莫须有』三字，何以服天下！」岳飞家产籍没，家属流放岭南，幕属宾客坐死、编窜者甚众。此狱一出，朝野主战之声尽息，南宋抗战派元气大伤。"
