    interpretation: "秦桧之为奸，非一夫之恶，实南宋皇权与和议政治的产物。高宗赵构南渡之后，深忌武人拥兵自重，更恐钦宗还朝、皇位不保，故和议、收兵权、诛岳飞三事皆是「上意」，秦桧不过最为得力的执行者。据《朱子语类》载，秦桧死后高宗曾言「朕今天始免得这柄快剑在此」，可见其君臣之间利用多于信任。然秦桧之罪又不止于承旨：十九年独相，台谏成其私器，文字之狱遍于四海，士大夫主战之脉为其尽断，南宋由此文弱偏安，恢复中原终成泡影。身后王爵见夺、谥号两改，正应了「青山有幸埋忠骨，白铁无辜铸佞臣」那一副对联。",
