      {
        heading: "财失其衡：岁币军费交困",
        paragraphs: [
          "冗官冗兵之外，又有岁币之费。景德二年（1005）澶渊之盟成，宋岁遗辽国银十万两、绢二十万匹，自此为常例。庆历二年（1042），辽乘宋夏交兵之机，遣使索关南之地，宋遣富弼使辽，许增岁币银十万两、绢十万匹，合计银二十万两、绢三十万匹，岁岁输送，无有穷已。及宋夏议和，复岁赐西夏银七万两、绢十五万三千匹、茶三万斤，亦成定例。此等岁出，名为「赐」而实为纳，徒耗国力，无补军实。",
          "三冗交并，国用大屈。真宗天禧年间，国家岁入尚有余裕；至仁宗庆历、皇祐年间，岁入缗钱三千余万，而所出常过其入，三司告匮，发内藏以补之，甚至预借民税、鬻卖度牒以充军须。国家一年所入，大半养兵，其次养官、养宗室，又以邦交岁币继之，用于兴利除弊、修治水利者十不二三。所谓「积贫」，非民贫而国贫，乃国家财赋结构支绌失衡之谓也。",
          "积贫积弱，人主忧之。庆历三年（1043）八月，仁宗召范仲淹为参知政事、富弼为枢密副使，责成更革。仲淹上《答手诏条陈十事》，其「明黜陟、抑侥幸、精贡举」，皆直指冗官之弊；「择官长」亦在澄汰不才。新政行未及一年，夏竦、王拱辰等攻讦不已，仲淹、富弼罢政出朝，旋即废罢。至神宗熙宁二年（1069），复起用王安石为参知政事，行均输、青苗、农田水利、免役诸法，以理财为先务，盖亦为三冗所困，不得不变。"
        ]
      }
