    interpretation: "三冗之弊，其源不在一二人之失政，而在立国之制度。宋惩唐末五代之乱，事事以「防弊」为先：分权以弱臣下，养兵以弭内乱，厚禄以养士人。三者皆所以收兵权、定秩序，其效亦著——北宋百余年无内乱、无藩镇之祸，为前代所罕见。然分权则官冗，养兵则兵冗，厚禄则费冗，制度运行既久，成本递增而效能递减，终致财用竭蹶、军伍不振。庆历新政欲以澄汰官吏入手，触犯既得之利，一期而废；熙宁变法转以理财为先，国库虽充，强兵之效有限。终宋之世，三冗未得根本解决，国家财政常在支绌之中，其间利害相倚、得失相伏，足资后世深省。",
