          "建炎南渡，局面全变。疆土蹙于淮汉，兵费糜于江淮，盐茶之利不足以赡，市舶遂为命脉所系。宋高宗曾发一言，足见其重：「市舶之利最厚，若措置合宜，所得动以百万计。」绍兴末年，泉、广两市舶司岁入达二百万贯。此数占岁入几何，史家说法不一：或以通贯全数计之，所占比有限；若计现钱岁入，则几及二成。要之，海贸利入已为南宋国用不可缺之一柱。",
