    interpretation: "市舶司表面是税关，实质是王朝国家把海洋财富纳入财政体系的一次成功尝试。它以公凭、抽解、博买、禁榷四环相扣，将舶货利润截留于官府，再经榷货务转卖变现，构成国有化经营链条。这与唐代市舶使奉宫廷之需、采奇珍以进的私属性质，判然有别：市舶司不再是皇帝的采办处，而是国家财政的造血器官。南宋以半壁江山支撑百五十年，市舶二百万贯之入，论比例史家尚有争议，其支柱作用则无异辞。泉州刺桐港之崛起、宋舶远航之壮举、指南针之用于舟师，皆有此制度为后盾。明代市舶司改主朝贡，海利反流入民间海商与走私者之手，国用遂失一柱。",
