    summary: "苏辙（1039—1112），字子由，眉州眉山人，苏洵之子、苏轼之弟。嘉祐二年（1057）与兄同榜登进士第，后又同举制科，名动京师。历仕仁宗、英宗、神宗、哲宗四朝，元祐间官至尚书右丞、门下侍郎，位列执政，力主革除新法之弊，又以蜀党之魁卷入党争，绍圣后屡遭贬谪，晚年退居许州颍滨。其文汪洋澹泊、秀杰内敛，与父苏洵、兄苏轼合称「三苏」，同列唐宋八大家。著有《栾城集》等，寿七十四，谥文定。",
    background: "北宋中叶，仁宗朝承平既久，积弊渐显：冗官、冗兵、冗费交织，财政困窘，边备松弛。庆历新政昙花一现后，士大夫要求变革的呼声并未止息。嘉祐元年（1056），苏洵携苏轼、苏辙二子入京，将二人文章投献欧阳修，一时文名震动汴梁。次年欧阳修主持贡举，锐意革除浮靡的「太学体」，苏轼、苏辙同榜及第，仁宗读其策论，喜曰「为子孙得两宰相」。然而变法的时代风暴正在酝酿。熙宁二年（1069）王安石执政，青苗、免役、保甲诸法次第推行，朝堂分裂为新旧两党。苏辙以制科入第四等，任属官，因上书直言新法扰民，自请外放。神宗崩后，高太后听政，起用司马光，元祐更化全面废除新法；苏辙兄弟同被召还，苏辙自右司谏累迁至门下侍郎，身处国政中枢。元祐八年（1093）哲宗亲政，绍述神宗法度，新党复起，苏辙连贬知汝州、袁州、筠州，最后安置雷州。他的一生，正嵌在北宋由盛转衰、党争由政见之争沦为意气倾轧的转折之上。",
