    interpretation: "苏辙一生的浮沉，是北宋党争最清晰的刻度尺。他与兄长苏轼的差别，不在政见高下，而在处世之道：苏轼锋芒外露，屡蹈必死之地；苏辙沉静简默，进退之间更有法度。元祐年间他位至门下侍郎，掌诰谏、参大政，所争者不是一法之存废，而是「君子小人之进退」与「宽猛缓急之节」——他认为司马光尽废新法、章惇尽复新法，皆是「矫枉过正」，国家元气由此斫伤。这一判断，为后来北宋的衰亡所印证。徽宗朝蔡京以「元祐党籍碑」禁锢旧党，士大夫元气尽毁，方有靖康之祸。文学上，他以「养气」论文，开宋文重学养、重格调一路，与乃兄的才子之文双峰并峙。后人常叹：眉山苏氏一门三父子，道德文章，皆为百代之师，而苏辙以其汪洋澹泊之作与稳健持重之政，证明他并非兄长之附庸，而足自立于千古。",
