    dynasty: "宋",
    era: "淳祐七年",
    year: {
      start: 1247
    },
    summary: "《洗冤集录》南宋淳祐七年（1247年）成书，作者宋慈，全书五卷，是中国历史上第一部系统的法医学专著。宋慈总结历代检验经验与自身任提点刑狱官的办案心得，书中载验尸、验骨、验伤、验毒、解毒及验死之法，提出「狱事莫重于大辟，大辟莫重于初情，初情莫重于检验」的断案原则。原刊本早佚，今存最早为元刻本。该书较欧洲同类专著早约三百五十年，先后被译为荷兰、法、德、英、日、朝鲜等文字，是世界法医学史上的里程碑。",
    background: "宋代司法检验制度之完备，为前代所未有。《宋刑统》沿袭唐律，规定检验不实者治罪；凡杀伤人命案件，州县官吏必须亲临检验，填报检验格目，逐级申报。淳熙元年（1174年），浙西提刑郑兴裔进《检验格目》，将检验文书与程式固定下来，颁行诸路。其时又有郑克《折狱龟鉴》、桂万荣《棠阴比事》等书，汇集历代折狱定谳之例，为检验之学积累经验。然而法立于上，弊生于下，检验之事繁难琐碎，官吏稍有不慎，则冤滥随之。宋慈，字惠父，福建路建宁府建阳人，嘉定十年（1217年）登进士第（另有嘉定十三年之说），历任主簿、知县，后长期在广东、江西、湖南任提点刑狱官，专司一路刑狱。他在任上审案理狱，平反冤案甚多，深感检验乃定谳之根本，乃博采《内恕录》以下诸家之书，益以己见，撰成此书。",
    chapters: [
      {
        heading: "提刑一生，惠父其人",
        paragraphs: [
          "宋慈，字惠父，福建路建宁府建阳县人，生于淳熙十三年（1186年）。他于嘉定十年（1217年）登进士第（登第年份，文献另有嘉定十三年之说），初任赣州信丰县主簿，后转任长汀知县。长汀地处山区，民贫俗悍，官府科盐于民，弊病深重。宋慈到任后，蠲免盐捐，整饬吏治，百姓得以安宁。",
          "淳祐初年，宋慈先后在广东、江西、湖南任提点刑狱官，掌一路刑狱纠察之权。提点刑狱司简称提刑司，是宋代路级司法监察机构，凡疑难命案、冤滞狱讼，皆归其复核。宋慈在任上审案理狱，决事刚果，平反冤假错案甚多，以「听讼清明」见称于时。淳祐八年（1248年），他升任广东经略安抚使；淳祐九年（1249年）病逝，享年六十四岁。宋慈半生仕路，皆与刑狱相终始，这正是《洗冤集录》成书的根基。"
        ]
      },
      {
        heading: "淳祐成书，五卷五十三目",
        paragraphs: [
          "淳祐七年（1247年），宋慈在湖南提点刑狱任上撰成《洗冤集录》，并自为序。序中开宗明义：「狱事莫重于大辟，大辟莫重于初情，初情莫重于检验。」大辟即死刑，初情即案发初始之情，三者层层递进，归结于检验一事。宋慈自言，此书博采近世所传《内恕录》以下数家之书，参以历年审案心得，删芜存精，编次成帙。原刊本早佚，今存最早者为元刻本，题《宋提刑洗冤集录》，全书五卷五十三目。",
          "全书五卷，结构完备。卷一载宋代检验法令与格目程式，明定检验官的职责与违式之罚；卷二、卷三详述验尸、验骨、验伤之法，以及自缢、溺死、焚死、受杖死、雷击死等各类死因的现场鉴别；卷四、卷五汇集中毒之检验与解毒急救方药。自法令制度、现场检验以至验毒解救，一书兼备，自成完整体系。书中各目多以实例与检验要点相参，条分缕析，便于检验官照章施行。"
        ]
      },
      {
        heading: "验尸验骨，辨伤识毒",
        paragraphs: [
          "《洗冤集录》最精妙处，在于对尸体现象的细致观察。书中「四时变动」一目，指出尸温下降、尸斑显现、尸体腐败之迟速，随春夏秋冬气温不同而各异，检验必须按时令推断死亡时辰，不可一概而论。验伤之时，以酒糟、醋、白梅汤、五倍子等洗敷伤处，使皮下瘀血显现；若伤痕隐而不露，则以桐油伞遮蔽日光，迎光照看骨上血晕，骨折与伤痕即可一一辨明，世称「红伞验骨」。",
          "辨伤之外，书中于死因鉴别尤有创获。自缢与被勒、自投水与被推溺、自焚与被烧，其尸表征象各有差异，书中逐一比较，教人分辨真伪。验毒一法，用银钗探入死者喉中，取出若变黑色，则疑为中毒。此法沿袭甚久，然以今日科学观之，银遇硫化物即黑，非砒霜所独有，未可一概而论。惟书中反复强调验毒须审慎、须合众证，不可专凭一端，其审慎态度已难能可贵。卷四、卷五所载解砒霜毒、解蛊毒诸方，亦多为历代经验之方。"
        ]
      },
      {
        heading: "东传西译，惠及后世",
        paragraphs: [
          "《洗冤集录》问世之后，历代检验官奉为圭臬。元代重刻是书，明清两代刑部与地方官署屡有刊行，注家蜂起。清康熙三十三年（1694年），律例馆奉旨校正《洗冤录》，删繁就简，定为四卷，颁行天下，成为清代官方检验的法定标准本。凡州县检验命案，检验官须按册施行，违式有罚。《洗冤集录》由一部私家著作，一变而为通行数百年的司法检验规程，其于刑狱之影响，实为难匹。",
          "在世界上，是书成于1247年，较欧洲第一部系统的法医学专著——意大利人费德利于1602年在威尼斯出版的《医生的报告》——早约三百五十年。十七世纪以后，《洗冤集录》先后被译为荷兰文、法文、德文、英文、日文、朝鲜文等多种文字，为各国法医学界所重视。现代法医学虽凭借解剖学、化学与显微技术远超前代，然《洗冤集录》所奠定的以检验求真相、以证据定谳的司法精神，至今仍是法医学的根本准则。"
        ]
      }
    ],
    interpretation: "《洗冤集录》成于南宋，并非偶然。宋代人口繁庶、商旅往来频繁，刑狱益繁；而制度上，提点刑狱司设一路之权责，检验格目立一文之程式，使检验有法可依、有章可循。宋慈以提刑官亲历其事，方能集其大成。其书价值，不止于技术。书中反复致意者，乃「狱事莫重于大辟」一层：人命至重，一旦错判，死者不可复生。它将儒家慎刑恤狱之理念，化为可逐条施行的检验规程，使仁政落到实处。限于时代，书中未解人体解剖之秘，银钗验毒、红伞验骨诸法亦有其失。然其重证据、重勘验、不轻信口供的精神，实已开近代法医学之先声，故后世校正颁行，东西各国遂相译介。",
