          "宋室南渡后，法式仍行于官府；金、元营建中都、大都，多循宋制；清代《工程做法则例》实为其流变。1919 年，朱启钤在南京江南图书馆发现丁氏八千卷楼抄本，此书始重见天日；1925 年陶湘据仿宋刻本刊行，学界乃得深入研讨。梁思成自 1930 年代起潜心研究，著《营造法式注释》，誉之为中国建筑学宝典，并以之解读独乐寺、佛光寺等辽宋遗构，中国建筑史研究由此开一新局。"
