    interpretation: "《营造法式》之深意，不止于技术。其一，它将建筑营造纳入国家财政与礼制秩序：材分八等、屋分数级，是等级社会在空间上的投影；功限料例则把王安石变法「量功计料」的理财之术落为可操作的工程账簿。其二，材份制以「材」为祖、以「份」为度，构件比例与施工皆可推算，使设计与施工标准化、模数化，较之西方同类制度早出数百年。其三，图样保留宋代建筑形制与纹样，为解读独乐寺、晋祠、保国寺等遗构提供了钥匙。它既是法典，也是中国木构体系成熟期的技术总结。",
