    summary: "曾巩（1019—1083），字子固，建昌军南丰（今江西南丰）人，北宋文学家、名臣。嘉祐二年（1057）进士，出自欧阳修门下，与苏轼、苏辙同榜。其文雍容典重、说理透辟，上承韩柳、下开宋调，位列唐宋八大家。历任馆阁校勘、越州通判及齐、襄、洪、福、明、亳、沧七州长官，任上均徭役、救灾荒、惩豪强、罢岁贡，政绩斐然。元丰五年拜中书舍人，修五朝国史。元丰六年卒于江宁府，年六十五。有《元丰类稿》五十卷传世。",
    background: "北宋中期，仁宗朝的科举与文风正经历一场变革。西昆体雕琢浮艳，朝野渐倡经世致用之文，欧阳修遂以翰林学士知嘉祐二年贡举，黜落险怪奇涩之卷，取平实晓畅者，一日之间拔擢曾巩、苏轼、苏辙同榜，世称龙虎榜。曾巩出身南丰曾氏，家学深厚：祖父曾致尧为太平兴国八年进士，官至户部郎中，以刚直敢言闻；父曾易占亦由进士入仕，官太常博士。然其早岁坎坷，景祐三年（1036）入京应试不第，庆历元年（1041）再入太学，文名渐起。庆历七年（1047），父卒于南京，曾巩扶柩归乡，从此奉侍继母，抚育曾布、曾肇等弟妹十余人，家境困顿而学业不废。正是这场家世变故与儒家涵养，铸成他文章沉稳厚重、关切民政的底色，也使他成为欧阳修古文阵营的中坚。",
