          "熙宁四年（1071），曾巩出知齐州（今山东济南）。齐州多大姓，豪族与猾吏勾结为奸，曾巩悉发其状，绳之以法。章丘民聚众村落，号「霸王社」，椎埋剽掠，白昼夺人牛马；曾巩设计擒捕首恶，处以死刑，余党远窜，州境肃然。他又以治水著称：疏导泺水，修北水门泄大明湖潦水，筑百花堤于湖上，济南人至今指为曾堤，后世复建南丰祠以祀。熙宁六年（1073）移知襄州，九年（1076）移知洪州（今江西南昌），逢江西大疫、岁荒，下令设病坊救治，出官粮赈济，禁囤积居奇。",
