    interpretation: "曾巩在后世的形象，长期被两层光圈遮蔽：一是唐宋八大家的文学光环，二是王安石、苏轼的时代光芒。其实他正是观察北宋士大夫政治的典型样本。欧阳修门下，他无苏轼之才气横溢，亦无王安石之锐意更张，却把古文的条理直接用于州县治理：平徭役、复陂湖、禁盗贼、罢岁贡，件件是钱谷刑名的实务。朱熹称其「醇于儒」，所赞不止于文，更在于人——在北宋儒学复兴中，他代表把经术落实为政事的一路。南宋以后曾文渐成科举范本，明茅坤《唐宋八大家文钞》出，其经典地位遂定，影响直至桐城派；而《宋史》「纡徐而不烦，简奥而不晦」之评，可谓文品人品的盖棺定论。",
