    interpretation: "赵普之历史地位，首在「定制度」。唐末五代，帝王废立操于武将之手，五十年间易姓者八。普以「稍夺其权、制其钱谷、收其精兵」九字为纲领，将藩镇兵、财、政三权一一收归中央：禁军分领于三衙，将不得专其兵；置转运使，州郡财赋悉输京师；知州、通判并设，以文臣领州事。宋祚三百余年，终未再演陈桥故事，普之功也。然矫枉过正，兵将分离而军威不振，州郡虚弱而边患岁币，终成宋室痼疾。其三起三落，亦见宋代君权独运、相权受抑之大势。以一幕僚而定三百年治平之基，虽史笔于其倾陷廷美之事屡有微词，终不失为一代佐命名相。",
