          "庆元二年（1196）十二月，监察御史沈继祖罗织朱熹十罪，诏落职罢祠，门人蔡元定编管道州。朝廷禁用「道学」二字，科举考卷稍涉义理者皆遭黜落，列朱熹等五十九人为伪学党籍，史称「庆元党禁」。朱熹晚年困居考亭，仍讲学著述不辍，庆元四年（1198）成《楚辞集注》。庆元六年（1200）三月初九，朱熹卒于建阳考亭沧洲精舍，享年七十一岁，葬于建阳大林谷。"
