    interpretation: "朱熹以「理」为万物本原，认为天地运行、君臣父子、春夏秋冬各有其「当然之则」，此即天理；人的私意与过度之欲即为人欲。「存天理，灭人欲」并非禁绝正常欲求，而是要求人君节用、士人修身、百姓各安本分。他倡「格物致知」，主张即事观理、由博返约，把道德修养建立在认知与践履之上。这套体系把佛老的精微思辨收摄入儒学，使儒家在形而上层面足以与二氏抗衡。从庆元党禁到从祀孔庙不过四十年，从被斥「伪学」到科举圭臬不过百年，理学终为宋以后历代王朝所尊，在于它为君主提供正心诚意的约束，为士大夫提供出处进退的准则，为乡村社会提供礼义秩序的蓝本，并随典籍与移民传入朝鲜、日本、越南，成为东亚文明的共同底色。",
