          "同年十一月，金军第二次大举南下，京城告急。朝廷授赵构为兵马大元帅，宗泽为副元帅，檄集诸路勤王之师。宗泽率军自磁州南下，转战于开德、卫南一线，十三战皆捷，一度进至滑州，逼近开封。然诸路兵马各有观望，大元帅府中汪伯彦等主张拥兵自保，宗泽孤军难以深入。靖康二年（1127）四月，京城陷落，徽钦二帝被俘北去，宗泽勤王之师终未及救援。"
