          "宗泽以恢复为志，深知单靠正规军不足御金，乃广招两河义军。王善拥众数十万，杨进号「没角牛」，聚众数万，宗泽皆单骑入其营，推诚抚慰，晓以民族大义，众皆听命。短时间内收编义军号称百万，声势大振，河东、河北各路义军亦纷纷联络，愿受节制。金人畏惮，不敢正视开封，军中呼为「宗爷爷」。",
          "宗泽又于军中拔擢岳飞。岳飞因犯法当斩，宗泽见其相貌奇伟，释而用之，授以统制之职，并授以阵图。岳飞答以「阵而后战，兵法之常，运用之妙，存乎一心」，宗泽深以为然，知其必为将才。宗泽坐镇东京一年有余，屡败金兵：建炎元年冬遣将破金军于开封近郊，建炎二年春滑州、韦城再战又捷，开封遂成金军南下途中难以逾越的屏障。"
